// Generated by zdoc. Resolves the mermaid bundle, preferring a
// vendored copy so the documentation renders without network access.
const MermaidURL = 'https://cdn.jsdelivr.net/npm/mermaid@11/dist/mermaid.esm.min.mjs';
const blocks = document.querySelectorAll('pre.mermaid');
if (blocks.length > 0) {
	let mermaid;
	try {
		mermaid = (await import(MermaidURL)).default;
	} catch (err) {
		for (const el of blocks) {
			el.classList.add('mermaid-error');
			el.setAttribute('title', String(err));
		}
	}
	if (mermaid) {
		mermaid.initialize({ startOnLoad: false });
		for (const el of blocks) {
			try {
				const { svg } = await mermaid.render(
					'm' + Math.random().toString(36).slice(2),
					el.textContent
				);
				el.innerHTML = svg;
			} catch (err) {
				// A malformed diagram should not blank the page; leave
				// the source visible so the author can still read it.
				el.classList.add('mermaid-error');
				el.setAttribute('title', String(err));
			}
		}
	}
}
